232	/* -----------------------------------------------------------
233	  Thread local data
234	----------------------------------------------------------- */
235	
236	static mi_tld_t* mi_tld_init(mi_tld_t* tld, size_t tseq, mi_subproc_t* subproc) {
237	  tld->subproc = subproc;
238	  tld->theaps = NULL;
239	  mi_lock_init(&tld->theaps_lock);
240	  if (tld->thread_id == MI_THREADID_DETACHED) {
241	    tld->numa_node = -1;
242	  }
243	  else {
244	    tld->numa_node = _mi_os_numa_node();
245	    tld->thread_id = _mi_prim_thread_id();
246	    tld->is_in_threadpool = _mi_prim_thread_is_in_threadpool();
247	    tld->thread_seq = tseq;
248	    mi_atomic_increment_relaxed(&tld->subproc->thread_count);
249	  }
250	  return tld;
251	}
252	
253	// Allocate fresh tld
254	static mi_tld_t* mi_tld_create(mi_subproc_t* subproc) {
255	  mi_assert_internal(subproc->theap_meta != NULL); // should be initialized on the main thread before other threads allocate
256	  const size_t tseq = mi_atomic_increment_relaxed(&subproc->thread_total_count);
257	
258	  mi_memid_t memid;
259	  mi_tld_t* tld;
260	  if (_mi_subproc_is_main(subproc) && tseq==0 /* first tld */) {
261	    tld = &mi_process_tld_main;
262	    memid = _mi_memid_create_static(tld,sizeof(*tld));
263	  }
264	  else {
265	    tld  = (mi_tld_t*)_mi_meta_zalloc(subproc, sizeof(mi_tld_t), &memid);
266	  }
267	  if (tld==NULL) {
268	    _mi_error_message(ENOMEM, "unable to allocate memory for thread local data\n");
269	    return NULL;
270	  }
271	  tld->memid = memid;
272	  return mi_tld_init(tld,tseq,subproc);
273	}
274	
275	mi_decl_noinline static void mi_tld_free(mi_tld_t* tld) {
276	  if (tld==NULL) return;
277	  mi_atomic_decrement_relaxed(&tld->subproc->thread_count);
278	  tld->thread_id = (mi_threadid_t)(~0);          // it is best to set an invalid tid for tld_main as sometimes the same thread-id
279	                                                 // is reused by the OS after a thread has terminated. (see issue #1287)
280	  mi_lock_done(&tld->theaps_lock);
281	  _mi_meta_free(tld->subproc, tld, tld->memid);  // note: safe for static tld
282	}
