285	/* -----------------------------------------------------------
286	  Thread Init
287	----------------------------------------------------------- */
288	
289	#if MI_DEBUG || defined(MI_TLS_RECURSE_GUARD)
290	static mi_theap_t* mi_heap_check_for_existing_theap(mi_heap_t* heap) {
291	  const mi_threadid_t tid = _mi_thread_id();
292	  mi_theap_t* thread_theap = NULL;
293	  mi_lock(&heap->theaps_lock) {
294	    for(mi_theap_t* theap = heap->theaps; theap != NULL; theap = theap->hnext ) {
295	      if (theap->tld->thread_id == tid) {
296	        thread_theap = theap;
297	        break;
298	      }
299	    }
300	  }
301	  return thread_theap;
302	}
303	#endif
304	
305	// Initialize thread
306	mi_theap_t* _mi_thread_init_with_heap(mi_heap_t* heap_main)
307	{
308	  // ensure our process has started already
309	  mi_process_init();
310	
311	  // if the theap_default is already set we have already initialized
312	  mi_theap_t* theap = _mi_theap_default();
313	  if (mi_theap_is_initialized(theap)) return theap;
314	
315	  // initialize the default theap
316	  // note: we cannot access thread-locals yet as that can cause (recursive) allocation
317	  // (on macOS <= 14 for example where the loader allocates thread-local data on demand).
318	  if (heap_main==NULL) {
319	    heap_main = mi_heap_main();
320	    mi_assert_internal(heap_main == &mi_process_heap_main);
321	  }
322	  mi_assert_internal(heap_main!=NULL);
323	
324	  #if MI_DEBUG || defined(MI_TLS_RECURSE_GUARD)
325	  theap = mi_heap_check_for_existing_theap(heap_main);  // recursion check
326	  #if !defined(MI_TLS_RECURSE_GUARD)
327	  mi_assert_internal(theap==NULL);
328	  #endif
329	  #else
330	  theap = NULL;
331	  #endif
332	
333	  if (theap==NULL) {
334	    // allocated the tld
335	    mi_tld_t* tld = mi_tld_create(heap_main->subproc);
336	    if (tld==NULL) return NULL;    // out-of-memory on tld allocation
337	    // allocate and initialize the theap for the main heap
338	    if (tld==&mi_process_tld_main) {
339	      theap = &mi_process_theap_main;          // initial theap is pre-allocated
340	      theap->memid = _mi_memid_create_static(theap,sizeof(*theap));
341	    }
342	    else {
343	      theap = _mi_theap_alloc(heap_main,tld);  // otherwise meta allocate
344	      if (theap==NULL) { mi_tld_free(tld); return NULL; } // out-of-memory on theap allocation
345	    }
346	    _mi_theap_init(theap,heap_main,tld);
347	  }
348	
349	  // now initialize the thread
350	  _mi_theap_default_set(theap);
351	  // and only then set the heap_theap field as that accesses thread locals
352	  _mi_heap_theap_set(heap_main, theap);  // todo: can fail!
353	
354	  mi_assert_internal(mi_theap_is_initialized(theap));
355	  mi_theap_t* const heap_theap = (heap_main==NULL ? NULL : (mi_theap_t*)_mi_thread_local_get(heap_main->theap));
356	  mi_assert_internal(heap_main==NULL || heap_theap == theap); MI_UNUSED_RELEASE(heap_theap);
357	
358	  mi_subproc_stat_increase(_mi_theap_subproc(theap), threads, 1);  // or theap stats and wait for merge?
359	  // _mi_verbose_message("thread init: 0x%zx\n", _mi_thread_id());
360	  return theap;
361	}
362	
363	mi_theap_t* _mi_thread_init(void) {
364	  return _mi_thread_init_with_heap(NULL);
365	}
