500	// Returns true if mimalloc was redirected
501	mi_decl_nodiscard bool mi_is_redirected(void) mi_attr_noexcept {
502	  return _mi_is_redirected();
503	}
504	
505	// Called once by the process loader from `src/prim/prim.c` before `main` is called.
506	void _mi_auto_process_init(void) {
507	  os_preloading = false;
508	
509	  mi_process_init();
510	  mi_process_setup_auto_thread_done();
511	
512	  _mi_options_post_init();  // now we can print to stderr
513	  if (_mi_is_redirected()) _mi_verbose_message("malloc is redirected.\n");
514	
515	  // show message from the redirector (if present)
516	  const char* msg = NULL;
517	  _mi_allocator_init(&msg);
518	  if (msg != NULL && (mi_option_is_enabled(mi_option_verbose) || mi_option_is_enabled(mi_option_show_errors))) {
519	    _mi_fputs(NULL,NULL,NULL,msg);
520	  }
521	
522	  // reseed random
523	  mi_theap_t* theap = _mi_theap_default();
524	  if (theap != NULL) {
525	    _mi_random_reinit_if_weak(&theap->random);
526	    mi_subproc_t* subproc = _mi_theap_subproc(theap);
527	    if (subproc->theap_meta != NULL) {
528	      mi_lock(&subproc->theap_meta_lock) {
529	        _mi_random_reinit_if_weak(&subproc->theap_meta->random);
530	      }
531	    }
532	  }
533	}
534	
535	
536	// Initialize the process; called by thread_init, the process loader, or an initial allocation (perhaps by the loader or a system library)
537	static void mi_process_init_once(void) {
538	  #if defined(__CYGWIN__)   // we need to kickstart the cygwin runtime
539	  __mi_thread_id_helper = NULL;
540	  #endif
541	  _mi_verbose_message("process init: 0x%zx\n", _mi_thread_id());
542	
543	  _mi_detect_cpu_features();
544	  _mi_options_init();        // read environment (if possible)
545	  _mi_stats_init();          // start timer
546	  _mi_os_init();             // primitive dependent
547	
548	  mi_heap_main_init();       // before page_map_init so stats are working
549	  _mi_page_map_init();       // todo: this could fail.. should we abort in that case?
550	  mi_thread_init();
551	
552	  // the following can potentially allocate (on freeBSD for pthread keys)
553	  _mi_tls_slots_init();      // pthread key create
554	  _mi_thread_locals_init();  // pthread key create
555	  _mi_process_is_initialized = true;
556	
557	  #if defined(_WIN32) && defined(MI_WIN_INIT_USE_FLS)
558	  // On windows, when building as a static lib the FLS cleanup happens to early for the main thread.
559	  // To avoid this, set the FLS value for the main thread to NULL so the fls cleanup
560	  // will not call _mi_thread_done on the (still executing) main thread. See issue #508.
561	  _mi_prim_thread_associate_default_theap(NULL);
562	  #endif
563	
564	  // mi_stats_reset();  // only call stat reset *after* thread init (or the theap tld == NULL)
565	  mi_track_init();
566	  if (mi_option_is_enabled(mi_option_reserve_huge_os_pages)) {
567	    size_t pages = mi_option_get_clamp(mi_option_reserve_huge_os_pages, 0, 128*1024);
568	    int reserve_at  = (int)mi_option_get_clamp(mi_option_reserve_huge_os_pages_at, -1, INT_MAX);
569	    if (reserve_at != -1) {
570	      mi_reserve_huge_os_pages_at(pages, reserve_at, pages*500);
571	    } else {
572	      mi_reserve_huge_os_pages_interleave(pages, 0, pages*500);
573	    }
574	  }
575	  if (mi_option_is_enabled(mi_option_reserve_os_memory)) {
576	    long ksize = mi_option_get(mi_option_reserve_os_memory);
577	    if (ksize > 0) {
578	      mi_reserve_os_memory((size_t)ksize*MI_KiB, true, true);
579	    }
580	  }
581	
582	  #if MI_PAGE_META_IS_ALIGNED
583	  mi_assert_internal((sizeof(mi_page_t)%MI_SIZE_SIZE) == 0);  // or page->zoffset might not work
584	  #endif
585	}
586	
587	// Initialize the process; called by thread_init or the process loader
588	void mi_process_init(void) mi_attr_noexcept {
589	  mi_atomic_do_once {
590	    mi_process_init_once();
591	  }
592	}
593	
594	
595	// Called when the process is done
596	static void mi_process_done_once(void) {
597	  // only shutdown if we were initialized
598	  if (!_mi_process_is_initialized) return;
599	  // ensure we are called once
600	  static bool process_done = false;
601	  if (process_done) return;
602	  process_done = true;
603	
604	  // decref any cached theap
605	  _mi_theap_cached_set(_mi_theap_empty_get());
606	
607	  // release any thread specific resources and ensure _mi_thread_done is called on all but the main thread
608	  _mi_prim_thread_done_auto_done();
609	
610	  #ifndef MI_SKIP_COLLECT_ON_EXIT
611	    #if (MI_DEBUG || !defined(MI_SHARED_LIB))
612	    // free all memory if possible on process exit. This is not needed for a stand-alone process
613	    // but should be done if mimalloc is statically linked into another shared library which
614	    // is repeatedly loaded/unloaded, see issue #281.
615	    mi_theap_collect(_mi_theap_default(), true /* force */);
616	    #endif
617	  #endif
618	
619	  // done with tracking tools
620	  mi_track_done();
621	
622	  // Forcefully release all retained memory; this can be dangerous in general if overriding regular malloc/free
623	  // since after process_done there might still be other code running that calls `free` (like at_exit routines,
624	  // or C-runtime termination code.
625	  mi_subproc_t* subproc_main = _mi_subproc_main();
626	  if (mi_option_is_enabled(mi_option_destroy_on_exit)) {
627	    _mi_subprocs_unsafe_destroy_all(); // destroys all mi_subprocs, arenas, thread locals, and the page_map!
628	  }
629	  else {
630	    // free dynamic thread locals (if used at all)
631	    _mi_thread_locals_thread_done();
632	    _mi_thread_locals_done();
633	    if (subproc_main->heap_main != NULL) {
634	      if (mi_option_is_enabled(mi_option_show_stats) || mi_option_is_enabled(mi_option_verbose)) {
635	        _mi_theap_merge_stats(subproc_main->theap_meta);
636	        _mi_theap_merge_stats(_mi_theap_default());  // _mi_thread_locals_done can free
637	        mi_heap_stats_merge_to_subproc(subproc_main->heap_main);
638	        mi_subproc_stats_print_out(mi_subproc_main(), NULL, NULL); // note: can try to access (the now freed) thread_locals in mi_heap_theap_peek
639	      }
640	    }
641	  }
642	
643	  _mi_tls_slots_done();
644	  _mi_subproc_main_done();
645	  _mi_allocator_done();
646	  _mi_verbose_message("process done %zu\n", sizeof(mi_page_t)); // : 0x%zx\n", mi_process_tld_main.thread_id);
647	  os_preloading = true; // don't call the C runtime anymore
648	}
649	
650	
651	// Call when the process is done (cdecl as it is used with `at_exit` on some platforms)
652	void mi_cdecl mi_process_done(void) mi_attr_noexcept {
653	  mi_atomic_do_once {
654	    mi_process_done_once();
655	  }
656	}
657	
658	// Called automatically when the process is done (cdecl as it is used with `at_exit` on some platforms)
659	void mi_cdecl _mi_auto_process_done(void) mi_attr_noexcept {
660	  if (_mi_option_get_fast(mi_option_destroy_on_exit)>=2) return;  // allow disabling auto process done
661	  mi_process_done();
662	}
