302	void mi_option_set(mi_option_t option, long value) {
303	  mi_assert(option >= 0 && option < _mi_option_last);
304	  if (option < 0 || option >= _mi_option_last) return;
305	  mi_option_desc_t* desc = &mi_options[option];
306	  mi_assert(desc->option == option);  // index should match the option
307	  desc->value = value;
308	  desc->init = MI_OPTION_INITIALIZED;
309	  // ensure min/max range; be careful to not recurse.
310	  if (desc->option == mi_option_guarded_min && _mi_option_get_fast(mi_option_guarded_max) < value) {
311	    mi_option_set(mi_option_guarded_max, value);
312	  }
313	  else if (desc->option == mi_option_guarded_max && _mi_option_get_fast(mi_option_guarded_min) > value) {
314	    mi_option_set(mi_option_guarded_min, value);
315	  }
316	}
