347	static void mi_cdecl mi_out_stderr(const char* msg, void* arg) {
348	  MI_UNUSED(arg);
349	  if (msg != NULL && msg[0] != 0) {
350	    _mi_prim_out_stderr(msg);
351	  }
352	}
353	
354	// Since an output function can be registered earliest in the `main`
355	// function we also buffer output that happens earlier. When
356	// an output function is registered it is called immediately with
357	// the output up to that point.
358	#ifndef MI_MAX_DELAY_OUTPUT
359	#define MI_MAX_DELAY_OUTPUT ((size_t)(16*1024))
360	#endif
361	static char out_buf[MI_MAX_DELAY_OUTPUT+1];
362	static _Atomic(size_t) out_len;
363	static mi_lock_t out_buf_lock = MI_LOCK_INITIALIZER;
364	
365	static void mi_cdecl mi_out_buf(const char* msg, void* arg) {
366	  MI_UNUSED(arg);
367	  if (msg==NULL) return;
368	  if (mi_atomic_load_acquire(&out_len)>=MI_MAX_DELAY_OUTPUT) return;
369	  size_t n = _mi_strlen(msg);
370	  if (n==0 || n >= MI_MAX_DELAY_OUTPUT) return;
371	  // copy msg into the buffer
372	  mi_lock(&out_buf_lock) {
373	    const size_t start = mi_atomic_add_acq_rel(&out_len, n);
374	    if (start < MI_MAX_DELAY_OUTPUT) {
375	      // check bound
376	      if (start+n >= MI_MAX_DELAY_OUTPUT) {
377	        n = MI_MAX_DELAY_OUTPUT-start-1;
378	      }
379	      _mi_memcpy(&out_buf[start], msg, n);
380	    }
381	  }
382	}
383	
384	static void mi_out_buf_flush(mi_output_fun* out, bool no_more_buf, void* arg) {
385	  if (out==NULL) return;
386	  // claim (if `no_more_buf == true`, no more output will be added after this point)
387	  mi_lock(&out_buf_lock) {
388	    size_t count = mi_atomic_add_acq_rel(&out_len, (no_more_buf ? MI_MAX_DELAY_OUTPUT : 1));
389	    // and output the current contents
390	    if (count>MI_MAX_DELAY_OUTPUT) count = MI_MAX_DELAY_OUTPUT;
391	    out_buf[count] = 0;
392	    out(out_buf,arg);
393	    if (!no_more_buf) {
394	      out_buf[count] = '\n'; // if continue with the buffer, insert a newline
395	    }
396	  }
397	}
398	
399	
400	// Once this module is loaded, switch to this routine
401	// which outputs to stderr and the delayed output buffer.
402	static void mi_cdecl mi_out_buf_stderr(const char* msg, void* arg) {
403	  mi_out_stderr(msg,arg);
404	  mi_out_buf(msg,arg);
405	}
406	
407	
408	
409	// --------------------------------------------------------
410	// Default output handler
411	// --------------------------------------------------------
412	
413	// The program should only install a single output handler from a single thread
414	// since otherwise the argument and output function may not match.
415	static _Atomic(void*) mi_out_default; // = // is `mi_output_fun*` (but some platforms don't support atomic function pointers)
416	static _Atomic(void*) mi_out_arg; // = NULL
417	
418	static mi_output_fun* mi_out_get_default(void** parg) {
419	  mi_output_fun* const out = (mi_output_fun*)mi_atomic_load_ptr_acquire(void,&mi_out_default);
420	  if (parg != NULL) { *parg = mi_atomic_load_ptr_acquire(void,&mi_out_arg); }
421	  return (out == NULL ? &mi_out_buf : out);
422	}
423	
424	void mi_register_output(mi_output_fun* out, void* arg) mi_attr_noexcept {
425	  mi_atomic_store_ptr_release(void,&mi_out_default, (void*)(out == NULL ? &mi_out_stderr : out)); // stop using the delayed output buffer
426	  mi_atomic_store_ptr_release(void,&mi_out_arg, arg);
427	  if (out!=NULL) { mi_out_buf_flush(out,true,arg); }        // output all the delayed output now
428	}
429	
430	// add stderr to the delayed output after the module is loaded
431	static void mi_add_stderr_output(void) {
432	  mi_assert_internal(mi_out_default == NULL);
433	  mi_out_buf_flush(&mi_out_stderr, false, NULL); // flush current contents to stderr
434	  mi_atomic_store_ptr_release(void,&mi_out_default,(void*)&mi_out_buf_stderr);  // and add stderr to the delayed output
435	  mi_atomic_store_ptr_release(void,&mi_out_arg,NULL);
436	}
437	
438	// --------------------------------------------------------
439	// Messages, all end up calling `_mi_fputs`.
440	// --------------------------------------------------------
441	static _Atomic(size_t) error_count;   // = 0;  // when >= max_error_count stop emitting errors
442	static _Atomic(size_t) warning_count; // = 0;  // when >= max_warning_count stop emitting warnings
443	
444	static mi_decl_noinline bool mi_recurse_enter_prim(void) {
445	  return true;
446	}
447	
448	static mi_decl_noinline void mi_recurse_exit_prim(void) {
449	  /* nothing */
450	}
451	
452	static bool mi_recurse_enter(void) {
453	  #if defined(__APPLE__) || defined(__ANDROID__) || defined(MI_TLS_RECURSE_GUARD)
454	  if (_mi_preloading()) return false;
455	  #endif
456	  return mi_recurse_enter_prim();
457	}
458	
459	static void mi_recurse_exit(void) {
460	  #if defined(__APPLE__) || defined(__ANDROID__) || defined(MI_TLS_RECURSE_GUARD)
461	  if (_mi_preloading()) return;
462	  #endif
463	  mi_recurse_exit_prim();
464	}
465	
466	void _mi_fputs(mi_output_fun* out, void* arg, const char* prefix, const char* message) {
467	  if (out==NULL || (void*)out==(void*)stdout || (void*)out==(void*)stderr) { // todo: use mi_out_stderr for stderr?
468	    if (!mi_recurse_enter()) return;
469	    out = mi_out_get_default(&arg);
470	    if (prefix != NULL) out(prefix, arg);
471	    out(message, arg);
472	    mi_recurse_exit();
473	  }
474	  else {
475	    if (prefix != NULL) out(prefix, arg);
476	    out(message, arg);
477	  }
478	}
