480	// Define our own limited `fprintf` that avoids memory allocation.
481	// We do this using `_mi_vsnprintf` with a limited buffer.
482	static void mi_vfprintf( mi_output_fun* out, void* arg, const char* prefix, const char* fmt, va_list args ) {
483	  char buf[992];
484	  if (fmt==NULL) return;
485	  if (!mi_recurse_enter()) return;
486	  _mi_vsnprintf(buf, sizeof(buf)-1, fmt, args);
487	  mi_recurse_exit();
488	  _mi_fputs(out,arg,prefix,buf);
489	}
490	
491	void _mi_fprintf( mi_output_fun* out, void* arg, const char* fmt, ... ) {
492	  va_list args;
493	  va_start(args,fmt);
494	  mi_vfprintf(out,arg,NULL,fmt,args);
495	  va_end(args);
496	}
497	
498	static void mi_vfprintf_thread(mi_output_fun* out, void* arg, const char* prefix, const char* fmt, va_list args) {
499	  if (prefix != NULL && _mi_strnlen(prefix,33) <= 32) { // && !_mi_is_main_thread()) {
500	    char tprefix[64];
501	    _mi_snprintf(tprefix, sizeof(tprefix), "%sthread 0x%tx: ", prefix, (uintptr_t)_mi_thread_id());
502	    mi_vfprintf(out, arg, tprefix, fmt, args);
503	  }
504	  else {
505	    mi_vfprintf(out, arg, prefix, fmt, args);
506	  }
507	}
508	
509	void _mi_raw_message(const char* fmt, ...) {
510	  va_list args;
511	  va_start(args, fmt);
512	  mi_vfprintf(NULL, NULL, NULL, fmt, args);
513	  va_end(args);
514	}
515	
516	void _mi_trace_message(const char* fmt, ...) {
517	  if (mi_option_get(mi_option_verbose) <= 1) return;  // only with verbose level 2 or higher
518	  va_list args;
519	  va_start(args, fmt);
520	  mi_vfprintf_thread(NULL, NULL, "mimalloc: ", fmt, args);
521	  va_end(args);
522	}
523	
524	void _mi_verbose_message(const char* fmt, ...) {
525	  if (!mi_option_is_enabled(mi_option_verbose)) return;
526	  va_list args;
527	  va_start(args,fmt);
528	  mi_vfprintf(NULL, NULL, "mimalloc: ", fmt, args);
529	  va_end(args);
530	}
531	
532	static void mi_show_error_message(const char* fmt, va_list args) {
533	  if (!mi_option_is_enabled(mi_option_verbose)) {
534	    if (!mi_option_is_enabled(mi_option_show_errors)) return;
535	    if (mi_max_error_count >= 0 && (long)mi_atomic_increment_acq_rel(&error_count) > mi_max_error_count) return;
536	  }
537	  mi_vfprintf_thread(NULL, NULL, "mimalloc: error: ", fmt, args);
538	}
539	
540	void _mi_warning_message(const char* fmt, ...) {
541	  if (!mi_option_is_enabled(mi_option_verbose)) {
542	    if (!mi_option_is_enabled(mi_option_show_errors)) return;
543	    if (mi_max_warning_count >= 0 && (long)mi_atomic_increment_acq_rel(&warning_count) > mi_max_warning_count) return;
544	  }
545	  va_list args;
546	  va_start(args,fmt);
547	  mi_vfprintf_thread(NULL, NULL, "mimalloc: warning: ", fmt, args);
548	  va_end(args);
549	}
550	
551	
552	#if MI_DEBUG
553	mi_decl_noreturn mi_decl_cold void _mi_assert_fail(const char* assertion, const char* fname, unsigned line, const char* func ) mi_attr_noexcept {
554	  _mi_fprintf(NULL, NULL, "mimalloc: assertion failed: at \"%s\":%u, %s\n  assertion: \"%s\"\n", fname, line, (func==NULL?"":func), assertion);
555	  abort();
556	}
557	#endif
558	
559	// --------------------------------------------------------
560	// Errors
561	// --------------------------------------------------------
562	
563	static mi_error_fun* volatile  mi_error_handler; // = NULL
564	static _Atomic(void*) mi_error_arg;     // = NULL
565	
566	static void mi_error_default(int err) {
567	  MI_UNUSED(err);
568	  #if (MI_DEBUG>0)
569	    if (err==EFAULT) {
570	      #ifdef _MSC_VER
571	      __debugbreak();
572	      #endif
573	      abort();
574	    }
575	  #endif
576	  #if (MI_SECURE>0)
577	    if (err==EFAULT) {  // abort on serious errors in secure mode (corrupted meta-data)
578	      abort();
579	    }
580	  #endif
581	  #if defined(MI_XMALLOC)
582	    if (err==ENOMEM || err==EOVERFLOW || err==EINVAL) { // abort on memory allocation fails in xmalloc mode
583	      abort();
584	    }
585	  #endif
586	  if (errno==0) {
587	    errno = (err==EINVAL ? EINVAL : ENOMEM /* compatibility */ );
588	  }
589	}
590	
591	void mi_register_error(mi_error_fun* fun, void* arg) {
592	  mi_error_handler = fun;  // can be NULL
593	  mi_atomic_store_ptr_release(void,&mi_error_arg, arg);
594	}
595	
596	void _mi_error_message(int err, const char* fmt, ...) {
597	  // show detailed error message
598	  va_list args;
599	  va_start(args, fmt);
600	  mi_show_error_message(fmt, args);
601	  va_end(args);
602	  // and call the error handler which may abort (or return normally, potentially setting errno)
603	  if (mi_error_handler != NULL) {
604	    mi_error_handler(err, mi_atomic_load_ptr_acquire(void,&mi_error_arg));
605	  }
606	  else {
607	    mi_error_default(err);
608	  }
609	}
610	
611	mi_decl_noinline mi_block_t* _mi_block_next_is_corrupted(const mi_page_t* page, const mi_block_t* block, const mi_block_t* next) {
612	  _mi_error_message(EFAULT, "corrupted free list entry of size %zub at %p: value 0x%zx\n", mi_page_block_size(page), block, (uintptr_t)next);
613	  return NULL;
614	}
615	    
616	// --------------------------------------------------------
617	// Initialize options by checking the environment
618	// --------------------------------------------------------
619	
620	// TODO: implement ourselves to reduce dependencies on the C runtime
621	#include <stdlib.h> // strtol
622	
623	static void mi_option_init(mi_option_desc_t* desc) {
624	  // Read option value from the environment
625	  char s[64 + 1];
626	  char buf[64+1];
627	  _mi_strlcpy(buf, "mimalloc_", sizeof(buf));
628	  _mi_strlcat(buf, desc->name, sizeof(buf));
629	  int err = _mi_getenv(buf, s, sizeof(s));
630	  if (err==ENOENT && desc->legacy_name != NULL) {
631	    _mi_strlcpy(buf, "mimalloc_", sizeof(buf));
632	    _mi_strlcat(buf, desc->legacy_name, sizeof(buf));
633	    err = _mi_getenv(buf, s, sizeof(s));
634	    if (err==0) {
635	      _mi_warning_message("environment option \"mimalloc_%s\" is deprecated -- use \"mimalloc_%s\" instead.\n", desc->legacy_name, desc->name);
636	    }
637	  }
638	
639	  if (err==0) {
640	    size_t len = _mi_strnlen(s, sizeof(buf) - 1);
641	    for (size_t i = 0; i < len; i++) {
642	      buf[i] = _mi_toupper(s[i]);
643	    }
644	    buf[len] = 0;
645	    if (buf[0] == 0 || _mi_streq(buf,"1") || _mi_streq(buf,"TRUE") || _mi_streq(buf,"YES") || _mi_streq(buf,"ON")) {
646	      desc->value = 1;
647	      desc->init = MI_OPTION_INITIALIZED;
648	    }
649	    else if (_mi_streq(buf,"0") || _mi_streq(buf,"FALSE") || _mi_streq(buf,"NO") || _mi_streq(buf,"OFF")) {
650	      desc->value = 0;
651	      desc->init = MI_OPTION_INITIALIZED;
652	    }
653	    else {
654	      char* end = buf;
655	      errno = 0;
656	      long value = strtol(buf, &end, 10);
657	      if (errno==0 && mi_option_has_size_in_kib(desc->option)) {
658	        // this option is interpreted in KiB to prevent overflow of `long` for large allocations
659	        // (long is 32-bit on 64-bit windows, which allows for 4TiB max.)
660	        size_t size = (value < 0 ? 0 : (size_t)value);
661	        bool overflow = false;
662	        if (*end == 'K') { end++; }
663	        else if (*end == 'M') { overflow = mi_mul_overflow(size,MI_KiB,&size); end++; }
664	        else if (*end == 'G') { overflow = mi_mul_overflow(size,MI_MiB,&size); end++; }
665	        else if (*end == 'T') { overflow = mi_mul_overflow(size,MI_GiB,&size); end++; }
666	        else { size = (size + MI_KiB - 1) / MI_KiB; }
667	        if (end[0] == 'I' && end[1] == 'B') { end += 2; } // KiB, MiB, GiB, TiB
668	        else if (*end == 'B') { end++; }                  // Kb, Mb, Gb, Tb
669	        if (overflow || size > (MI_MAX_ALLOC_SIZE / MI_KiB)) { size = (MI_MAX_ALLOC_SIZE / MI_KiB); }
670	        value = (size > LONG_MAX ? LONG_MAX : (long)size);
671	      }
672	      if (errno==0 && *end == 0) {
673	        mi_option_set(desc->option, value);
674	      }
675	      else {
676	        // set `init` first to avoid recursion through _mi_warning_message on mimalloc_verbose.
677	        desc->init = MI_OPTION_DEFAULTED;
678	        if (desc->option == mi_option_verbose && desc->value == 0) {
679	          // if the 'mimalloc_verbose' env var has a bogus value we'd never know
680	          // (since the value defaults to 'off') so in that case briefly enable verbose
681	          desc->value = 1;
682	          _mi_warning_message("environment option mimalloc_%s has an invalid value.\n", desc->name);
683	          desc->value = 0;
684	        }
685	        else {
686	          _mi_warning_message("environment option mimalloc_%s has an invalid value.\n", desc->name);
687	        }
688	      }
689	    }
690	    mi_assert_internal(desc->init != MI_OPTION_UNINIT);
691	  }
692	  else if (err==ENOENT) {
693	    desc->init = MI_OPTION_DEFAULTED;
694	  }
695	  // and on another error, keep unitialized to try again (can happen during preloading if getenv is not available)
696	}
